<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
auth(true);
$evento=(int)($_GET['event_id']??0);$carrera=trim((string)($_GET['carrera']??''));$tipo=trim((string)($_GET['category']??''));$buscar=trim((string)($_GET['buscar']??''));
$where=["r.status<>'Anulado'","COALESCE(r.payment_method,'')<>'Descuento por planilla'","r.category IN ('Estudiante','Estudiante BTH','UNIOR')"];$args=[];
if($evento){$where[]='r.event_id=?';$args[]=$evento;}if($carrera!==''){$where[]='r.carrera=?';$args[]=$carrera;}if($tipo!==''){$where[]='r.category=?';$args[]=$tipo;}if($buscar!==''){$where[]='(r.first_name LIKE ? OR r.last_name LIKE ? OR r.ci LIKE ?)';array_push($args,'%'.$buscar.'%','%'.$buscar.'%','%'.$buscar.'%');}
$registros=all('SELECT r.*,e.name evento_deuda FROM registrations r JOIN events e ON e.id=r.event_id WHERE '.implode(' AND ',$where).' ORDER BY r.carrera,r.last_name,r.first_name,r.id',$args);
$filas=[];$total=0;$pagado=0;$saldo=0;$resumen=[];
foreach($registros as $r){$c=resumenCobro($r);$grupo=!empty($r['codigo_grupo']);if($grupo&&tieneRecibosAnulados($r)){
 // El resumen del grupo se distribuye en el mismo orden y proporción que el cobro.
 $resto=$c['cobrado'];$base=$c['total'];$individual=0;
 foreach(integrantesGrupo($r) as $persona){$precio=(int)round($persona['price']*100);$parte=$base>0?min($precio,(int)round($resto*$precio/$base)):0;if((int)$persona['id']===(int)$r['id'])$individual=$parte;$resto-=$parte;$base-=$precio;}
 }else{$individual=$grupo?(int)round($r['monto_cobrado']*100):$c['cobrado'];}
 $precio=(int)round($r['price']*100);$debe=max(0,$precio-$individual);if(!$debe)continue;$r['cuenta_deuda']=$individual/100;$r['saldo_deuda']=$debe/100;$filas[]=$r;$total+=$precio;$pagado+=$individual;$saldo+=$debe;$key=$r['codigo_grupo']?:'persona-'.$r['id'];$resumen[$key]=true;}
$head=['Registro','Nombre completo','CI','Celular','Carrera','Tipo','Evento','Importe Bs','A cuenta Bs','Saldo Bs'];
$valores=fn($r)=>[$r['id'],nombreParticipante($r),$r['ci'],$r['phone'],$r['carrera'],$r['category'],$r['evento_deuda'],number_format($r['price'],2,'.',''),number_format($r['cuenta_deuda'],2,'.',''),number_format($r['saldo_deuda'],2,'.','')];
if(($_GET['exportar']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="deudas_estudiantes.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");$csv=function($v)use($f){fputcsv($f,array_map(fn($x)=>preg_match('/^[\s]*[=+@-]/u',(string)$x)?"'".$x:$x,$v),';','"','');};$csv($head);foreach($filas as $r)$csv($valores($r));$csv(['TOTAL','','','','','','',$total/100,$pagado/100,$saldo/100]);fclose($f);exit;}
headerPage('Deudas de estudiantes');estilosSaldoPendiente();
?>
<div class="card p-4 no-print"><form method="get"><input type="hidden" name="p" value="reporte_deudas_estudiantes"><div class="row"><div class="col-md-4"><?php selectField('event_id','Evento',[0=>'Todos']+array_column(all('SELECT id,name FROM events ORDER BY starts_at DESC'),'name','id'),(string)$evento);?></div><div class="col-md-4"><?php selectField('carrera','Carrera',[''=>'Todas']+carrerasInscripcion(),$carrera);?></div><div class="col-md-4"><?php selectField('category','Tipo',[''=>'Todos los estudiantes','Estudiante'=>'Estudiante','Estudiante BTH'=>'Estudiante BTH','UNIOR'=>'UNIOR'],$tipo);?></div></div><?php field('buscar','Nombre, apellido o CI',$buscar,'text',false);?><button class="btn btn-primary">Consultar</button> <button class="btn btn-success" name="exportar" value="csv">Exportar Excel (CSV)</button> <button type="button" class="btn btn-outline-primary" onclick="print()">Imprimir / PDF</button></form></div>
<div class="card p-4"><h3>UNIOR · Estudiantes con saldo pendiente</h3><p>Estudiante, Estudiante BTH y UNIOR. No incluye profesionales, anulados ni planilla. Cada integrante del grupo figura con su deuda individual.</p><p><b><?=count($filas)?> estudiantes · A cuenta: <?=money($pagado/100)?> · Saldo por cobrar: <?=money($saldo/100)?></b></p><div class="table-responsive"><table class="table table-bordered tabla-saldos"><thead><tr><?php foreach($head as $h):?><th><?=e($h)?></th><?php endforeach?><th class="no-print">Ficha</th></tr></thead><tbody><?php foreach($filas as $r):?><tr class="con-saldo"><?php foreach($valores($r) as $v):?><td><?=e($v)?></td><?php endforeach?><td class="no-print"><a class="btn btn-sm btn-primary" href="<?=url('p=participant&t='.$r['token'].'#pagos-saldo')?>">Cobrar saldo</a></td></tr><?php endforeach?><?php if(!$filas):?><tr><td colspan="11">No hay estudiantes con saldo pendiente para estos filtros.</td></tr><?php endif?></tbody></table></div></div>
<?php footerPage();
